package com.ias.ticket;

import com.ias.trust.Problem;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.mock.web.MockHttpServletRequest;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

/** Real H2 JDBC/transactions; identity facts are an explicit test port, not network evidence. */
public class ApprovalBoundaryTest {
 java.sql.Connection ddlConnection;
 JdbcTemplate db;Tickets tickets;ApprovalBoundary boundary;StaffAccess access;
 String ticket,round,assignment,operation;boolean record=true;Tickets.Actor actor;
 public static Timestamp utc(int precision){return Timestamp.from(Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MILLIS));}
 @BeforeEach void prepare()throws Exception{
  var ds=new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","sa","");
  ddlConnection=ds.getConnection();
  db=new JdbcTemplate(ds);var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setIsolationLevel(2);tx.setTimeout(5);tickets=new Tickets(db,tx);
  db.execute("CREATE ALIAS IF NOT EXISTS UTC_TIMESTAMP FOR 'com.ias.ticket.ApprovalBoundaryTest.utc'");
  db.execute("CREATE TABLE ticket_actor_lock(tenant_id BIGINT,user_id BIGINT,PRIMARY KEY(tenant_id,user_id))");
  db.execute("CREATE TABLE ticket_record(id CHAR(36) PRIMARY KEY,tenant_id BIGINT,round_id CHAR(36),assignment_id CHAR(36),company_id BIGINT,department_id BIGINT,engineer_user_id BIGINT,status VARCHAR(40),row_version BIGINT,current_cancel_request_id CHAR(36))");
  db.execute("CREATE TABLE ticket_round(id CHAR(36),ticket_id CHAR(36),PRIMARY KEY(id,ticket_id))");db.execute("CREATE TABLE ticket_assignment(id CHAR(36) PRIMARY KEY)");
  db.execute("CREATE TABLE ticket_audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,operation_id CHAR(36),tenant_id BIGINT,actor_user_id BIGINT,action VARCHAR(64),occurred_at TIMESTAMP(3))");
  try(var in=getClass().getResourceAsStream("/db/migration/V9__approval_reference_boundary.sql")){String sql=new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).replace("CHARACTER SET ascii COLLATE ascii_bin","").replace("ENGINE=InnoDB","");db.execute(sql);}
  try(var in=getClass().getResourceAsStream("/db/migration/V10__approval_settlement_boundary.sql")){ddlConnection.createStatement().execute(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).replace("CHARACTER SET ascii COLLATE ascii_bin","").replace("ENGINE=InnoDB",""));}
  ticket=UUID.randomUUID().toString();round=UUID.randomUUID().toString();assignment=UUID.randomUUID().toString();operation=UUID.randomUUID().toString();
  db.update("INSERT INTO ticket_record VALUES(?,7,?,?,9,5,42,'IN_PROGRESS',1,NULL)",ticket,round,assignment);db.update("INSERT INTO ticket_round VALUES(?,?)",round,ticket);db.update("INSERT INTO ticket_assignment VALUES(?)",assignment);
  actor=new Tickets.Actor(7,42,"EMPLOYEE",null,null,"trace",Long.MAX_VALUE,null);
  access=new StaffAccess(){@Override Map<String,Object> approvalFacts(Tickets.Actor a,String purpose){return facts(a);}@Override Map<String,Object> facts(Tickets.Actor a){return Map.of("enabled",true,"departmentEnabled",true,"tenantId",Long.toString(a.tenant()),"userId",Long.toString(a.user()),"departmentId","5","companyIds",List.of("9"),"permissions",a.user()==42?(record?List.of("ticket.engineer.read","ticket.record","approval.parts.read","approval.parts.submit"):List.of("ticket.engineer.read")):List.of("ticket.read"));}};
  boundary=new ApprovalBoundary(tickets,access);
 }
 Map<String,Object> register(){return boundary.register(ticket,round,assignment,operation,"a".repeat(64),actor);}
 long count(String table){return db.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);}
 long version(){return db.queryForObject("SELECT row_version FROM ticket_record WHERE id=?",Long.class,ticket);}
 @Test void originalUuidIsDurableAndReplayDoesNotWrite(){var one=register();var two=register();assertEquals(one.get("recordedAt"),two.get("recordedAt"));assertEquals("REGISTERED_INTENT",two.get("referenceState"));assertEquals(1,count("ticket_approval_reference"));assertEquals(1,count("ticket_audit"));assertEquals(2,version());assertEquals(409,assertThrows(Problem.class,()->boundary.register(ticket,round,assignment,operation,"b".repeat(64),actor)).status);}
 @Test void currentSubmissionPermissionPrecedesOriginalUuidReplay(){register();record=false;assertEquals(403,assertThrows(Problem.class,this::register).status);assertEquals(1,count("ticket_approval_reference"));assertEquals(2,version());}
 @Test void contextIsReadOnlyAndCompanyReaderCannotRegister(){var cs=new Tickets.Actor(7,43,"EMPLOYEE",null,null,"t",Long.MAX_VALUE,null);assertEquals("IN_PROGRESS",boundary.view(boundary.visible(ticket,cs)).get("status"));assertEquals(0,count("ticket_audit"));assertEquals(1,version());assertEquals(403,assertThrows(Problem.class,()->boundary.register(ticket,round,assignment,operation,"a".repeat(64),cs)).status);assertEquals(404,assertThrows(Problem.class,()->boundary.visible(ticket,new Tickets.Actor(8,42,"EMPLOYEE",null,null,"t",Long.MAX_VALUE,null))).status);}
 @Test void pendingCancellationAndOldRoundOrAssignmentCannotRegister(){db.update("UPDATE ticket_record SET current_cancel_request_id=?",UUID.randomUUID().toString());assertEquals("TICKET_NOT_APPROVABLE",assertThrows(Problem.class,this::register).code);db.update("UPDATE ticket_record SET current_cancel_request_id=NULL");assertEquals("ROUND_CONFLICT",assertThrows(Problem.class,()->boundary.register(ticket,UUID.randomUUID().toString(),assignment,operation,"a".repeat(64),actor)).code);assertEquals("ASSIGNMENT_CONFLICT",assertThrows(Problem.class,()->boundary.register(ticket,round,UUID.randomUUID().toString(),operation,"a".repeat(64),actor)).code);assertEquals(0,count("ticket_approval_reference"));}
 @Test void everyTerminalOrWaitingStateRejectsNewIntent(){for(String state:List.of("CANCELLED","CLOSED","RESOLVED","ASSIGNED","WAITING_INFORMATION")){db.update("UPDATE ticket_record SET status=?",state);assertEquals("TICKET_NOT_APPROVABLE",assertThrows(Problem.class,this::register).code);}assertEquals(0,count("ticket_approval_reference"));}
 @Test void auditFailureRollsBackIntentAndVersionThenOriginalKeyRecovers(){db.execute("ALTER TABLE ticket_audit ADD CONSTRAINT it_approval_audit CHECK(action<>'APPROVAL_REFERENCE_REGISTERED')");assertThrows(Exception.class,this::register);assertEquals(0,count("ticket_approval_reference"));assertEquals(0,count("ticket_audit"));assertEquals(1,version());db.execute("ALTER TABLE ticket_audit DROP CONSTRAINT it_approval_audit");register();assertEquals(1,count("ticket_approval_reference"));assertEquals(2,version());}
 @Test void cancellationAndIntentSerializeOnSameTicketLock()throws Exception{
  try(var pool=Executors.newVirtualThreadPerTaskExecutor()){
   var gate=new CountDownLatch(1);var submit=pool.submit(()->{gate.await();try{register();return true;}catch(Problem e){assertEquals("TICKET_NOT_APPROVABLE",e.code);return false;}});
   var cancel=pool.submit(()->{gate.await();try{return tickets.tx.execute(tx->{db.queryForMap("SELECT * FROM ticket_record WHERE id=? FOR UPDATE",ticket);boundary.requireNoExternal(ticket);db.update("UPDATE ticket_record SET status='CANCELLED',row_version=row_version+1 WHERE id=?",ticket);return true;});}catch(Problem e){assertEquals("UNSUPPORTED_RELATED_BUSINESS",e.code);return false;}});
   gate.countDown();assertNotEquals(submit.get(),cancel.get());assertEquals(2,version());assertEquals(count("ticket_approval_reference"),count("ticket_audit"));
  }
 }
 @Test void concurrentSameUuidCreatesOneReferenceAndAudit()throws Exception{try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var gate=new CountDownLatch(1);var tasks=new ArrayList<Future<?>>();for(int i=0;i<6;i++)tasks.add(pool.submit(()->{gate.await();return register();}));gate.countDown();for(var f:tasks)f.get();}assertEquals(1,count("ticket_approval_reference"));assertEquals(1,count("ticket_audit"));assertEquals(2,version());}
 @Test void bypassOrForgedInternalAttributeFailsClosed(){var controller=new ApprovalBoundaryController(tickets,access);var request=new MockHttpServletRequest();request.setSecure(true);request.setAttribute("ias.chain.edge","approval-ticket");assertEquals(403,assertThrows(Problem.class,()->controller.context(Map.of("sessionToken","synthetic-only","ticketId",ticket),request)).status);}
 @Test void intentPreservesWorkflowButRequiresApprovalOrPartsCleanupNotFeeSettlement(){register();var row=db.queryForMap("SELECT * FROM ticket_record WHERE id=?",ticket);assertEquals("IN_PROGRESS",row.get("status"));assertEquals(round,row.get("round_id"));assertEquals(assignment,row.get("assignment_id"));assertEquals("UNSUPPORTED_RELATED_BUSINESS",assertThrows(Problem.class,()->boundary.requireNoExternal(ticket)).code);assertTrue(Completion.supported(Map.of("completion_scope","ORDINARY_REPAIR_V1"),"DISABLED"));var check=new HashMap<String,Object>(Map.of("canClose",true,"relatedWorkflows","NOT_ENABLED","blockers",List.of()));boundary.annotateClosure(check,ticket);assertEquals(false,check.get("canClose"));assertEquals("APPROVAL_OR_PARTS_PENDING",check.get("relatedWorkflows"));assertEquals(false,check.get("externalOwnerCleanupVerified"));}
}

